#!/usr/bin/env python3
"""Generates cases.m from the names list, so a constant cannot go unasked. --check says whether the file
on disk is what the list says. The 18 are the kSecKeyAlgorithm constants; their VALUES are measured on
the host and are not in this file, which is the point: a name is not a value."""
import os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
NAMES = os.path.join(HERE, "algorithms.txt")
CASES = os.path.join(HERE, "cases.m")

def render(names):
    out = ['#import <Foundation/Foundation.h>', '#import <Security/Security.h>', '',
           '// GENERATED by gen-security-cases.py from the names list - a hand-copied list goes stale, and',
           '// fifteen TLS functions were once decided as implemented because their REASON read like a later',
           '// arrival. The list is the port own: these names are the SDK own, in both builds.', '']
    out += ['extern const CFStringRef %s;' % n for n in names]
    out += ['', 'void security_run(void (*record)(const char *, const char *))', '{']
    for n in names:
        out += ['    {',
                '        NSString *value = (__bridge NSString *)(%s);' % n,
                '        const char *utf8 = value.UTF8String;',
                '        record("%s", utf8 ? utf8 : "(unreadable)");' % n,
                '    }']
    out += ['}']
    return "\n".join(out) + "\n"

def main():
    names = sorted(l.strip() for l in open(NAMES) if l.strip())
    text = render(names)
    if "--check" in sys.argv:
        if open(CASES).read() == text:
            print("cases.m is what the list says: %d constants" % len(names))
            return 0
        print("FAIL cases.m is not what the list says")
        return 1
    open(CASES, "w").write(text)
    print("cases.m written: %d constants" % len(names))
    return 0

if __name__ == "__main__":
    sys.exit(main())
